import {
  Injectable,
  BadRequestException,
  ForbiddenException,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { Repository } from 'typeorm';
import { User } from './user.entity';
import { InjectRepository } from '@nestjs/typeorm';
import { hash, compare } from 'bcrypt';
import { UserDTO } from './user.dto';

export interface PasswordChangeDTO {
  oldPassword: string;
  newPassword: string;
  userId: number;
}

export interface EmailChangeDTO {
  userId: number;
  newEmail: string;
}

@Injectable()
export class UserService {
  constructor(
    @InjectRepository(User) private readonly userRepository: Repository<User>,
  ) {}

  async createOne(user: UserDTO): Promise<User> {
    if (!user.password) throw new BadRequestException('Password is required');
    const hashedPassword = await hash(user.password, 6);
    const userDTO: UserDTO = {
      ...user,
      password: hashedPassword,
    };
    return this.userRepository.save(userDTO);
  }

  async getUser(id: number): Promise<User | undefined> {
    return this.userRepository
      .createQueryBuilder()
      .where('id=:id', { id })
      .getOne();
  }

  async getUsers(): Promise<User[]> {
    return this.userRepository.createQueryBuilder().getMany();
  }

  async updatePassword(passwordChangeDTO: PasswordChangeDTO) {
    const user = await this.getUser(passwordChangeDTO.userId);
    if (!user) {
      throw new HttpException(
        `no user of id ${passwordChangeDTO.userId}`,
        HttpStatus.UNPROCESSABLE_ENTITY,
      );
    }
    const match = await compare(passwordChangeDTO.oldPassword, user.password);
    if (!match) throw new ForbiddenException('Invalid password');

    const hashedPassword = await hash(passwordChangeDTO.newPassword, 6);

    await this.userRepository.update(passwordChangeDTO.userId, {
      password: hashedPassword,
    });
  }

  async updateEmail(emailChangeDTO: EmailChangeDTO) {
    await this.userRepository.update(emailChangeDTO.userId, {
      email: emailChangeDTO.newEmail,
    });
  }
}

import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, getRepository, getConnection } from 'typeorm';
import { Strength } from '../user/entities/strength.entity';
import { Skill } from '../user/entities/skill.entity';
import { JobType } from '../user/entities/jobType.entity';
import { Admin } from './entities/admin.entity';
import { User } from '../user/entities/user.entity';
import { Company } from '../company/entities/company.entity';

import { CreateStrengthDto } from './dto/create-strength.dto';
import { CreateSkillDto } from './dto/create-skill.dto';
import { CreateJobTypeDto } from './dto/create-jobType.dto';
import { CreateAdminDto } from './dto/create-admin.dto';

import * as generator from 'generate-password';
import { UpdateUserAdminDto } from './dto/update-user-admin.dto';
import { UpdateCompanyAdminDto } from './dto/update-company-admin.dto';
import { UserCompany } from '../common/entities/userCompany.entity';

import * as bcrypt from 'bcryptjs';
import { MailService } from '../services/mail/mail.service';
import { JwtService } from '@nestjs/jwt';

@Injectable()
export class AdminService {

  constructor(
    @InjectRepository(Strength) private readonly strengthsRepository: Repository<Strength>,
    @InjectRepository(Skill) private readonly skillsRepository: Repository<Skill>,
    @InjectRepository(JobType) private readonly jobTypesRepository: Repository<JobType>,
    @InjectRepository(Admin) private readonly adminRepository: Repository<Admin>,
    @InjectRepository(User) private readonly userRepository: Repository<User>,
    @InjectRepository(Company) private readonly companyRepository: Repository<Company>,
    @InjectRepository(UserCompany) private readonly userCompanyRepository: Repository<UserCompany>,
    private readonly mailService: MailService,
    private readonly jwtService: JwtService
  ) { }

  /**
   * 
   * @param createStrengthDto DTO to encapsulate the createStrength data
   * @description Create strength
   */
  async createStrength(createStrengthDto: CreateStrengthDto): Promise<any> {
    return await this.strengthsRepository.save(createStrengthDto);
  }

  /**
   * 
   * @param createSkillDto DTO to encapsulate the createSkill data
   * @description Create skill
   */
  async createSkill(createSkillDto: CreateSkillDto): Promise<any> {
    return await this.skillsRepository.save(createSkillDto);
  }

  /**
   * 
   * @param createJobTypeDto DTO to encapsulate the createJobType data
   * @description Create a job type
   */
  async createJobType(createJobTypeDto: CreateJobTypeDto): Promise<any> {
    return await this.jobTypesRepository.save(createJobTypeDto);
  }

  async createAdmin(createAdminDto: CreateAdminDto): Promise<any> {
    const randomPassword = this.generateRandomPassword();
    createAdminDto.password = randomPassword;
    const entity = Object.assign(new Admin(), createAdminDto);
    const adminResponse = await this.adminRepository.save(entity);
    return {
      ...adminResponse,
      password: randomPassword
    };
  }

  /**
   * @description View all users in the database
   */
  async viewUsers(): Promise<any> {
    return await this.userRepository.find({ relations: ['company'] });
  }

  /**
   * 
   * @param id id of the user
   * @description View details of a particular user
   */
  async viewUser(id: string): Promise<any> {
    const user = await this.userRepository.findOne({ where: { id }, relations: ['company'] })
    let updatedBy: any = user;
    const admin = await this.adminRepository.findOne({ where: { id: user.updatedBy } });
    if (admin) {
      updatedBy = admin;
    }
    return {
      ...user,
      createdBy: user,
      updatedBy
    }
  }

import {
  ForbiddenException,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { hash, compare } from 'bcrypt';
import { sign } from 'jsonwebtoken';
import { User } from './user.entity';

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User) private readonly userRepository: Repository<User>,
  ) {}

  public async findOrStore(email: string, password: string) {
    const ex = await this.userRepository.findOne({ where: { email } });

    if (ex) {
      throw new ForbiddenException('This email is already taken!');
    }

    const user = new User();
    user.email = email;
    user.password = await hash(password, 10);
    await this.userRepository.save(user);

    return { email };
  }

  public async authOrFail(email: string, password: string) {
    const user = await this.userRepository.findOne({ where: { email } });

    if (!user || !(await compare(password, user.password))) {
      throw new UnauthorizedException('Incorrect email-password combination!');
    }

    return {
      token: sign({ ...user }, process.env.JWT_SECRET, { expiresIn: '1h' }),
    };
  }
}

import {ExtractJwt, Strategy} from 'passport-jwt';
import {PassportStrategy} from '@nestjs/passport';
import {Inject, Injectable, UnauthorizedException} from '@nestjs/common';
import {ConfigService} from '@nestjs/config';
import {EnvironmentVariables} from '../../common/EnvironmentVariables';
import {PayloadInterface} from '../dto/payload.interface';
import {UserService} from '../../user/user.service';
import {InjectRepository} from '@nestjs/typeorm';
import {User} from '../../user/entities/user.entity';
import {Repository} from 'typeorm';
@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(
    private readonly configService: ConfigService<EnvironmentVariables>,
    @InjectRepository(User) private readonly userRepository: Repository<User>,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: configService.get<string>('JWT_ACCESS_TOKEN_SECRET'),
    });
  }

  async validate(payload: PayloadInterface) {
    const username: string = payload.username;
    const user = await this.userRepository.findOne({where: {username}});

    // if the user is not null or undefined which means that we find it
    if (user) {
      delete user.salt;
      delete user.password;
      return user;
    } else {
      // if we don't find the user it means that he's unauthorized
      throw new UnauthorizedException();
    }
  }
}

import { Resolver, Query, Arg } from "type-graphql";
import { Repository, In } from "typeorm";
import { InjectRepository } from "typeorm-typedi-extensions";

import { Article } from "../schema/article";
import { User } from "../schema/user";

@Resolver(() => Article)
export class MainResolver {
  constructor(
    @InjectRepository(User) private readonly userRepository: Repository<User>,
    @InjectRepository(Article)
    private readonly articleRepository: Repository<Article>
  ) {}

  @Query(() => [Article], { nullable: true })
  async FetchOwnedArticlesByUid(@Arg("uid") uid: number): Promise<any> {
    // 还要做一个不存在的报错
    // 放在context里做吧
    const userInfo = await this.userRepository.findOne({
      where: { uid }
    });

    if (!userInfo) {
      return [];
    }
    const aids = userInfo
      .ownedArticles!.split(",")
      .map((item: string) => parseInt(item, 10));

    const articleCollections = await this.articleRepository.find({
      aid: In(aids)
    });
    return articleCollections;
  }
}

