        <SearchForm onSubmit={handleSearchByTech} closeModal={closeModal}/>
      </div>
      </aside>

      <main>
        <ul>
          <DevList addedDev={addedDev}/>
        </ul>
      </main>
    </div>
    </>
  );
}

