test('createObjectFromPath', () => {
  let payload, path, res
  path = 'nest.once'
  payload = true
  res = createObjectFromPath(path, payload)
  expect(res).toEqual({ nest: { once: true } })
  path = 'a.path.like.this'
  res = createObjectFromPath(path, payload)
