const checkDbHealth = async () => {
  try {
    const users = await User.count();
    if (users) {
      return true;
    }
  } catch (error) {
    return false;
  }
  return false;
};

const checkRedisHealth = async () => {
  try {
    await SET_ASYNC('health', 'check');
  } catch (error) {
    return false;
  }
  client.expire('health', 5);
  const reply = await GET_ASYNC('health');
  if (reply) {
    return true;
  }
  return false;
};

module.exports = {
