    var gallery = new Gallery(req.body);
    gallery.user = req.user;
    gallery.save(function(err) {
        if (err) {
            return res.send('users/signup', {
                errors: err.errors,
                gallery: gallery
            });
        } else {
            res.jsonp(gallery);
        }
    });
};

