exports.update = function(req, res) {
    var gallery = req.gallery;

    gallery = _.extend(gallery, req.body);

    gallery.save(function(err) {
        if (err) {
            return res.send('users/signup', {
                errors: err.errors,
                gallery: gallery
            });
        } else {
            res.jsonp(gallery);
        }
    });
};

