                batch.delete(self.rootRef.doc(header.headerDocID));
                if (header.contentDocID) {
                    batch.delete(self.rootRef.doc(header.contentDocID));
                }
            });
            return batch.commit();
        })
        .then(function () {
            self.clearCache();
            return Promise.resolve({
                userID: userID
            });
        })
        .catch(function (error) {
            return Promise.reject({
