			function(OwnerProperty) {
				$scope.hasProperty = OwnerProperty;
			});
        };

        $scope.findOne = function() {
            Properties.get({
                propertyId: $stateParams.propertyId
            }, function(property) {
                $scope.property = property;
            });
        };
